def reference_fix_spaces(text):
    res = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] != ' ':
            res.append(text[i])
            i += 1
        else:
            j = i
            while j < n and text[j] == ' ':
                j += 1
            run = j - i
            if run == 1:
                res.append('_')
            elif run == 2:
                res.append('__')
            else:
                res.append('-')
            i = j
    return ''.join(res)


def test_mixed_underscores_and_spaces():
    # underscore adjacent to space-run should be preserved
    assert fix_spaces("a_   b") == reference_fix_spaces("a_   b") == "a_-b"
    assert fix_spaces("a___   b") == "a___-b"
    assert fix_spaces("a   ___b") == "a-___b"
